//! The sign test, the two-sample Kolmogorov-Smirnov test, the median test, Friedman's ANOVA, the Grubbs and Dixon
//! outlier tests and the row statistics against numbers from Origin.
//!
//! Reference scripts in `tools/origin-ref/stats3/` (X-Functions `sign2`, `kstest2`, `mediantest`, `friedman`,
//! `grubbs`, `qtest`, `rowstats`); the inputs and Origin's numbers are in `fixtures/stats3_origin.rs`, made by
//! `stats3-make-fixture.py`. All inputs were generated by us.
//!
//! Tolerances: counts, statistics and exact Kolmogorov-Smirnov p-values agree to 1e-9 or better (Origin's
//! binomial tail of the sign test to 5e-6). Origin's t quantile is off by up
//! to 3e-6 relative and its chi-square and t tails by up to 2e-5, so the critical values and p-values that come
//! from them are compared with 2e-5. The large-sample Kolmogorov-Smirnov p-value is compared to 1e-7.

#[path = "fixtures/stats3_origin.rs"]
mod fixtures;

use fixtures::*;
use sheaf_calc::*;

fn tail(code: u8) -> Tail {
    [Tail::Two, Tail::Upper, Tail::Lower][code as usize]
}

/// Relative tolerance with a small absolute part for the far tail; NaN means Origin shows nothing.
fn near(name: &str, what: &str, got: f64, want: f64, rel: f64) {
    if want.is_nan() {
        assert!(got.is_nan(), "{name}: {what}: got {got:?}, Origin shows nothing");
        return;
    }
    assert!((got - want).abs() <= rel * want.abs() + 1e-12, "{name}: {what}: got {got:?}, Origin gave {want:?}");
}

#[test]
fn sign_test_matches_origin() {
    assert!(SIGN.len() > 40);
    for c in SIGN {
        let r = sign_test(c.a, c.b, tail(c.tail));
        let Some(r) = r else {
            assert!(c.p.is_nan(), "{}: no result but Origin gave p = {}", c.name, c.p);
            continue;
        };
        assert!(!c.p.is_nan(), "{}: Origin shows no p", c.name);
        assert_eq!([r.first_smaller as f64, r.second_smaller as f64, r.ties as f64], c.counts, "{}: counts", c.name);
        near(c.name, "statistic", r.statistic, c.stat, 1e-12);
        near(c.name, "z", r.z.unwrap_or(f64::NAN), c.z, 1e-9);
        near(c.name, "p", r.p, c.p, 5e-6);
    }
}

#[test]
fn two_sample_kolmogorov_smirnov_matches_origin() {
    assert!(KS.len() > 35);
    let mut exact = 0;
    let mut asymptotic = 0;
    for c in KS {
        let r = ks_two_sample(c.a, c.b, tail(c.tail));
        let Some(r) = r else {
            assert!(c.d.is_nan(), "{}: no result but Origin gave D = {}", c.name, c.d);
            continue;
        };
        assert_eq!((r.n1 as f64, r.n2 as f64), (c.n1, c.n2), "{}", c.name);
        near(c.name, "D", r.d, c.d, 1e-12);
        near(c.name, "Z", r.z, c.z, 1e-9);
        if r.exact {
            exact += 1;
            near(c.name, "p (exact)", r.p, c.p, 1e-9);
        } else {
            asymptotic += 1;
            near(c.name, "p (asymptotic)", r.p, c.p, 1e-7);
        }
    }
    assert!(exact > 30 && asymptotic >= 5, "{exact} exact and {asymptotic} asymptotic cases");
}

#[test]
fn median_test_matches_origin() {
    assert!(MEDIAN.len() >= 10);
    for c in MEDIAN {
        let groups: Vec<&[f64]> = c.groups.to_vec();
        let r = median_test(&groups).unwrap_or_else(|| panic!("{}: no result", c.name));
        near(c.name, "median", r.median, c.median, 1e-12);
        near(c.name, "chi-square", r.chi_square, c.chi2, 1e-9);
        near(c.name, "df", r.df, c.df, 0.0);
        near(c.name, "p", r.p, c.p, 2e-5);
    }
}

#[test]
fn friedman_matches_origin_and_refuses_missing_numbers_like_origin() {
    assert!(FRIEDMAN.len() >= 12);
    for c in FRIEDMAN {
        let cols: Vec<&[f64]> = c.cols.to_vec();
        let r = friedman(&cols).unwrap_or_else(|e| panic!("{}: {e}", c.name));
        for (i, g) in r.groups.iter().enumerate() {
            near(c.name, "mean rank", g.mean_rank, c.mean_ranks[i], 1e-12);
            near(c.name, "rank sum", g.rank_sum, c.rank_sums[i], 1e-12);
        }
        near(c.name, "chi-square", r.chi_square, c.chi2, 1e-9);
        near(c.name, "df", r.df, c.df, 0.0);
        if !c.p.is_nan() {
            near(c.name, "p", r.p, c.p, 2e-5);
        }
    }
    // Origin writes no report when a number is missing or the columns differ in length.
    assert_eq!(friedman(&[&[1.0, f64::NAN, 3.0], &[2.0, 2.0, 4.0]]), Err(FriedmanError::Incomplete(2)));
    assert_eq!(friedman(&[&[1.0, 2.0, 3.0, 4.0], &[2.0, 3.0, 4.0]]), Err(FriedmanError::Incomplete(4)));
}

#[test]
fn grubbs_matches_origin() {
    assert!(GRUBBS.len() >= 25);
    for c in GRUBBS {
        let r = grubbs(c.data, c.alpha).unwrap_or_else(|e| panic!("{}: {e}", c.name));
        near(c.name, "suspect value", r.value, c.value, 1e-12);
        near(c.name, "row", r.index as f64, c.index, 0.0);
        near(c.name, "G", r.g, c.stat, 1e-9);
        near(c.name, "critical value", r.critical, c.critical, 2e-5);
        near(c.name, "p", r.p, c.p, 2e-5);
        near(c.name, "significant", f64::from(u8::from(r.significant)), c.significant, 0.0);
    }
    // No result: fewer than three numbers, all numbers equal.
    assert!(grubbs(&[1.0, 2.0], 0.05).is_err());
    assert_eq!(grubbs(&[3.0; 5], 0.05), Err(OutlierError::AllEqual));
}

#[test]
fn dixon_q_matches_origin() {
    assert!(DIXON.len() >= 30);
    for c in DIXON {
        let r = dixon_q(c.data, c.alpha).unwrap_or_else(|e| panic!("{}: {e}", c.name));
        near(c.name, "suspect value", r.value, c.value, 1e-12);
        near(c.name, "row", r.index as f64, c.index, 0.0);
        near(c.name, "Q", r.q, c.stat, 1e-9);
        near(c.name, "critical Q", r.critical, c.critical, 1e-12);
        near(c.name, "significant", f64::from(u8::from(r.significant)), c.significant, 0.0);
    }
    // Origin has the table for 3 to 10 numbers only.
    assert!(dixon_q(&[1.0, 2.0], 0.05).is_err());
    assert!(dixon_q(&[0.5, 3.1, 3.2, 3.4, 3.3, 3.15, 3.25, 3.35, 3.3, 3.2, 3.28], 0.05).is_err());
}

#[test]
fn row_statistics_match_origin() {
    assert!(ROWSTATS.len() >= 4);
    for c in ROWSTATS {
        for (r, want) in c.rows.iter().enumerate() {
            let values: Vec<f64> = c.cols.iter().map(|col| col[r]).collect();
            let s = row_stats(&values);
            let got = [s.mean, s.sd, s.sem, s.min, s.max, s.n, s.sum];
            for (k, (g, w)) in got.iter().zip(want).enumerate() {
                near(c.name, &format!("row {} quantity {k}", r + 1), *g, *w, 1e-12);
            }
        }
    }
}
